    public MandelbrotZ5Calculator(int width, int height) => Resize(width, height);

    public void Resize(int width, int height)
    {
        Width  = width;
        Height = height;
        ColorBuffer = new uint[width * height];
        IterationBuffer = new int[width * height];
        SmoothBuffer = new float[width * height];
    }

    public void Calculate(CancellationToken ct = default)
    {
        ColorMap.MaxIterations = MaxIterations;
        double scale = (3.5 / Math.Max(Width, Height)) / Zoom;
        _lastPixelScale = scale;
        LastPrecisionLabel = "SP";

        // GPU path: opt-in, lazy init, automatic fallback.
        if (UseGpu && TryRenderGpu(scale, ct)) { LastPrecisionLabel = "GPU"; return; }

        // Perturbation is the deep-zoom workhorse — DD/QD reference orbit
        // computed ONCE for the frame, then double-precision δ per pixel
        // (cheap). Per-pixel glitch detection inside the loop falls back
        // to HP-direct for individual misbehaving pixels, so the slow path
        // only pays for the small fraction of pixels that need it. When
        // the reference orbit itself escapes (centre is outside the set
        // at deep zoom) TryRenderPerturbation returns false and the
        // whole-frame HP-direct fallback below takes over.
        if (SupportsPerturbation && UsePerturbation && Zoom >= PerturbZoomThreshold && TryRenderPerturbation(scale, ct))
            return;

        // Whole-frame HP-direct fallback (reference orbit escaped, or the
        // user opted out of perturbation at deep zoom). Slow — DD/QD per
        // pixel from iter 0 — but correct at any zoom DD/QD can represent.
        if (Zoom >= DdDeltaZoomThreshold)
        {
            TryRenderHpDirect(scale, ct);
            return;
        }

        bool useAvx = Avx2.IsSupported && Fma.IsSupported && Width >= 4;

        Parallel.For(0, Height, new ParallelOptions { CancellationToken = ct }, y =>
        {
            if (ct.IsCancellationRequested) return;
            double dy = (y - Height * 0.5) * scale;
            double ciScalar = CenterY + dy;
            int rowBase = y * Width;
            int x = 0;
            if (useAvx)
            {
                var ciVec = Vector256.Create(ciScalar);
                for (; x + 4 <= Width; x += 4)
                {
                    double cx0 = CenterX + (x     - Width * 0.5) * scale;
                    double cx1 = CenterX + (x + 1 - Width * 0.5) * scale;
                    double cx2 = CenterX + (x + 2 - Width * 0.5) * scale;
                    double cx3 = CenterX + (x + 3 - Width * 0.5) * scale;
                    var crVec = Vector256.Create(cx0, cx1, cx2, cx3);
                    IterateLaneAvx2(crVec, ciVec, ColorBuffer, rowBase + x);
                }
            }
            for (; x < Width; x++)
            {
                double cx = CenterX + (x - Width * 0.5) * scale;
                IteratePixelScalar(cx, ciScalar, ColorBuffer, rowBase + x);
            }
        });
    }

