            double di_new = ((((((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zr - (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zi) + ((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi)) * zr - (((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zi + (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zr) + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr)) * zi) + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zr - ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zi)) * di + (((((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zr - (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zi) + ((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi)) * zi + (((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zi + (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zr) + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr)) * zr) + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zi + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zr)) * dr);
            double zr_new = (((((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zr - ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zi) * zr - (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zi + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zr) * zi) + cr);
            double zi_new = (((((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zr - ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zi) * zi + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zi + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zr) * zr) + ci);
            zr = zr_new; zi = zi_new;
            dr = dr_new; di = di_new;
        }
        zrOut = zr; ziOut = zi; drOut = dr; diOut = di;
        return it;
    }

    // ── AVX2 path (4 pixels per lane) ───────────────────────────────────────

    private void IterateLaneAvx2(Vector256<double> cr, Vector256<double> ci, uint[] buf, int idx)
    {
        Vector256<double> zr = Vector256<double>.Zero;
        Vector256<double> zi = Vector256<double>.Zero;
        Vector256<double> dr = Vector256<double>.Zero;
        Vector256<double> di = Vector256<double>.Zero;
        Vector256<double> bailoutVec = Vector256.Create(Bailout2);
        Vector256<long> itCounts = Vector256<long>.Zero;
        Vector256<long> oneL = Vector256.Create(1L);
        Vector256<long> activeLanes = Vector256.Create(-1L);   // all lanes active initially

        int maxIt = MaxIterations;
        for (int n = 0; n < maxIt; n++)
        {
            var r2 = Fma.MultiplyAdd(zr, zr, Avx.Multiply(zi, zi));
            // active = (r2 < bailout) — lanes that have NOT yet escaped
            var activeMaskD = Avx.Compare(r2, bailoutVec, FloatComparisonMode.OrderedLessThanNonSignaling);
            var activeMaskL = activeMaskD.AsInt64();
            activeLanes = Avx2.And(activeLanes, activeMaskL);
            if (Avx.MoveMask(activeMaskD) == 0) break;
            itCounts = Avx2.Add(itCounts, Avx2.And(oneL, activeMaskL));

                Vector256<double> d_re1 = Avx.Add(zr, zr);
                Vector256<double> d_im2 = Avx.Add(zi, zi);
                Vector256<double> d_re3 = Fma.MultiplyAddNegated(d_im2, zi, Avx.Multiply(d_re1, zr));
                Vector256<double> d_im4 = Fma.MultiplyAdd(d_re1, zi, Avx.Multiply(d_im2, zr));
                Vector256<double> d_re5 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> d_im6 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> d_re7 = Avx.Add(d_re3, d_re5);
                Vector256<double> d_im8 = Avx.Add(d_im4, d_im6);
                Vector256<double> d_re9 = Fma.MultiplyAddNegated(d_im8, zi, Avx.Multiply(d_re7, zr));
                Vector256<double> d_im10 = Fma.MultiplyAdd(d_re7, zi, Avx.Multiply(d_im8, zr));
                Vector256<double> d_re11 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> d_im12 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> d_re13 = Fma.MultiplyAddNegated(d_im12, zi, Avx.Multiply(d_re11, zr));
                Vector256<double> d_im14 = Fma.MultiplyAdd(d_re11, zi, Avx.Multiply(d_im12, zr));
                Vector256<double> d_re15 = Avx.Add(d_re9, d_re13);
                Vector256<double> d_im16 = Avx.Add(d_im10, d_im14);
                Vector256<double> d_re17 = Fma.MultiplyAddNegated(d_im16, zi, Avx.Multiply(d_re15, zr));
                Vector256<double> d_im18 = Fma.MultiplyAdd(d_re15, zi, Avx.Multiply(d_im16, zr));
                Vector256<double> d_re19 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> d_im20 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> d_re21 = Fma.MultiplyAddNegated(d_im20, zi, Avx.Multiply(d_re19, zr));
                Vector256<double> d_im22 = Fma.MultiplyAdd(d_re19, zi, Avx.Multiply(d_im20, zr));
                Vector256<double> d_re23 = Fma.MultiplyAddNegated(d_im22, zi, Avx.Multiply(d_re21, zr));
                Vector256<double> d_im24 = Fma.MultiplyAdd(d_re21, zi, Avx.Multiply(d_im22, zr));
                Vector256<double> d_re25 = Avx.Add(d_re17, d_re23);
                Vector256<double> d_im26 = Avx.Add(d_im18, d_im24);
                Vector256<double> d_re27 = Fma.MultiplyAddNegated(d_im26, di, Avx.Multiply(d_re25, dr));
                Vector256<double> d_im28 = Fma.MultiplyAdd(d_re25, di, Avx.Multiply(d_im26, dr));
                Vector256<double> d_re29 = Vector256.Create(1.0);
                Vector256<double> d_re30 = Avx.Add(d_re27, d_re29);
                Vector256<double> dr_new = d_re30;
                Vector256<double> di_new = d_im28;
                Vector256<double> z_re1 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> z_im2 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> z_re3 = Fma.MultiplyAddNegated(z_im2, zi, Avx.Multiply(z_re1, zr));
                Vector256<double> z_im4 = Fma.MultiplyAdd(z_re1, zi, Avx.Multiply(z_im2, zr));
                Vector256<double> z_re5 = Fma.MultiplyAddNegated(z_im4, zi, Avx.Multiply(z_re3, zr));
                Vector256<double> z_im6 = Fma.MultiplyAdd(z_re3, zi, Avx.Multiply(z_im4, zr));
                Vector256<double> z_re7 = Fma.MultiplyAddNegated(z_im6, zi, Avx.Multiply(z_re5, zr));
                Vector256<double> z_im8 = Fma.MultiplyAdd(z_re5, zi, Avx.Multiply(z_im6, zr));
                Vector256<double> z_re9 = Avx.Add(z_re7, cr);
                Vector256<double> z_im10 = Avx.Add(z_im8, ci);
                Vector256<double> zr_new = z_re9;
                Vector256<double> zi_new = z_im10;

            // Freeze z, dz/dc for any lane that escaped this iteration; live
            // lanes pick up the new values.
            var keepD = activeMaskL.AsDouble();
            zr = Avx.BlendVariable(zr, zr_new, keepD);
            zi = Avx.BlendVariable(zi, zi_new, keepD);
            dr = Avx.BlendVariable(dr, dr_new, keepD);
            di = Avx.BlendVariable(di, di_new, keepD);
        }

        Span<long> its = stackalloc long[4];
        Span<double> zrs = stackalloc double[4];
        Span<double> zis = stackalloc double[4];
        Span<double> drs = stackalloc double[4];
        Span<double> dis = stackalloc double[4];
        itCounts.CopyTo(its);
        zr.CopyTo(zrs); zi.CopyTo(zis);
        dr.CopyTo(drs); di.CopyTo(dis);
        for (int k = 0; k < 4; k++)
            buf[idx + k] = ColorFor((int)its[k], zrs[k], zis[k], drs[k], dis[k], MaxIterations, idx + k);
    }

    // Iteration-count-only variant for the self-test (no colour writeback).
    internal void IterateLaneAvx2Raw(Vector256<double> cr, Vector256<double> ci,
                                      Span<int> outIters)
    {
        Vector256<double> zr = Vector256<double>.Zero;
        Vector256<double> zi = Vector256<double>.Zero;
        Vector256<double> dr = Vector256<double>.Zero;
        Vector256<double> di = Vector256<double>.Zero;
        Vector256<double> bailoutVec = Vector256.Create(Bailout2);
        Vector256<long> itCounts = Vector256<long>.Zero;
        Vector256<long> oneL = Vector256.Create(1L);

        int maxIt = MaxIterations;
        for (int n = 0; n < maxIt; n++)
        {
            var r2 = Fma.MultiplyAdd(zr, zr, Avx.Multiply(zi, zi));
            var activeMaskD = Avx.Compare(r2, bailoutVec, FloatComparisonMode.OrderedLessThanNonSignaling);
            var activeMaskL = activeMaskD.AsInt64();
            if (Avx.MoveMask(activeMaskD) == 0) break;
            itCounts = Avx2.Add(itCounts, Avx2.And(oneL, activeMaskL));

                Vector256<double> d_re1 = Avx.Add(zr, zr);
                Vector256<double> d_im2 = Avx.Add(zi, zi);
                Vector256<double> d_re3 = Fma.MultiplyAddNegated(d_im2, zi, Avx.Multiply(d_re1, zr));
                Vector256<double> d_im4 = Fma.MultiplyAdd(d_re1, zi, Avx.Multiply(d_im2, zr));
                Vector256<double> d_re5 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> d_im6 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> d_re7 = Avx.Add(d_re3, d_re5);
                Vector256<double> d_im8 = Avx.Add(d_im4, d_im6);
                Vector256<double> d_re9 = Fma.MultiplyAddNegated(d_im8, zi, Avx.Multiply(d_re7, zr));
                Vector256<double> d_im10 = Fma.MultiplyAdd(d_re7, zi, Avx.Multiply(d_im8, zr));
                Vector256<double> d_re11 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> d_im12 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> d_re13 = Fma.MultiplyAddNegated(d_im12, zi, Avx.Multiply(d_re11, zr));
                Vector256<double> d_im14 = Fma.MultiplyAdd(d_re11, zi, Avx.Multiply(d_im12, zr));
                Vector256<double> d_re15 = Avx.Add(d_re9, d_re13);
                Vector256<double> d_im16 = Avx.Add(d_im10, d_im14);
                Vector256<double> d_re17 = Fma.MultiplyAddNegated(d_im16, zi, Avx.Multiply(d_re15, zr));
                Vector256<double> d_im18 = Fma.MultiplyAdd(d_re15, zi, Avx.Multiply(d_im16, zr));
                Vector256<double> d_re19 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> d_im20 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> d_re21 = Fma.MultiplyAddNegated(d_im20, zi, Avx.Multiply(d_re19, zr));
                Vector256<double> d_im22 = Fma.MultiplyAdd(d_re19, zi, Avx.Multiply(d_im20, zr));
                Vector256<double> d_re23 = Fma.MultiplyAddNegated(d_im22, zi, Avx.Multiply(d_re21, zr));
                Vector256<double> d_im24 = Fma.MultiplyAdd(d_re21, zi, Avx.Multiply(d_im22, zr));
                Vector256<double> d_re25 = Avx.Add(d_re17, d_re23);
                Vector256<double> d_im26 = Avx.Add(d_im18, d_im24);
                Vector256<double> d_re27 = Fma.MultiplyAddNegated(d_im26, di, Avx.Multiply(d_re25, dr));
                Vector256<double> d_im28 = Fma.MultiplyAdd(d_re25, di, Avx.Multiply(d_im26, dr));
                Vector256<double> d_re29 = Vector256.Create(1.0);
                Vector256<double> d_re30 = Avx.Add(d_re27, d_re29);
                Vector256<double> dr_new = d_re30;
                Vector256<double> di_new = d_im28;
                Vector256<double> z_re1 = Fma.MultiplyAddNegated(zi, zi, Avx.Multiply(zr, zr));
                Vector256<double> z_im2 = Fma.MultiplyAdd(zr, zi, Avx.Multiply(zi, zr));
                Vector256<double> z_re3 = Fma.MultiplyAddNegated(z_im2, zi, Avx.Multiply(z_re1, zr));
                Vector256<double> z_im4 = Fma.MultiplyAdd(z_re1, zi, Avx.Multiply(z_im2, zr));
                Vector256<double> z_re5 = Fma.MultiplyAddNegated(z_im4, zi, Avx.Multiply(z_re3, zr));
                Vector256<double> z_im6 = Fma.MultiplyAdd(z_re3, zi, Avx.Multiply(z_im4, zr));
                Vector256<double> z_re7 = Fma.MultiplyAddNegated(z_im6, zi, Avx.Multiply(z_re5, zr));
                Vector256<double> z_im8 = Fma.MultiplyAdd(z_re5, zi, Avx.Multiply(z_im6, zr));
                Vector256<double> z_re9 = Avx.Add(z_re7, cr);
                Vector256<double> z_im10 = Avx.Add(z_im8, ci);
                Vector256<double> zr_new = z_re9;
                Vector256<double> zi_new = z_im10;

            var keepD = activeMaskL.AsDouble();
            zr = Avx.BlendVariable(zr, zr_new, keepD);
            zi = Avx.BlendVariable(zi, zi_new, keepD);
            dr = Avx.BlendVariable(dr, dr_new, keepD);
            di = Avx.BlendVariable(di, di_new, keepD);
        }

        Span<long> its = stackalloc long[4];
        itCounts.CopyTo(its);
        for (int k = 0; k < 4; k++) outIters[k] = (int)its[k];
    }

    // ── ILGPU path (Tier 6) ─────────────────────────────────────────────────
    //
    // Generated kernel: one work item per pixel. Iterates in plain
    // scalar `double` (same body as the CPU scalar path, no SIMD) and
    // writes a RawPixel struct. CPU post-pass runs IColorMap.Map across
    // the buffer in parallel so the theme system remains live.

    public struct GpuParams
    {
        public int Width;
        public int Height;
        public double CenterX;
        public double CenterY;
        public double Scale;
        public int MaxIter;
        public double Bailout2;
    }

    public struct RawPixel
    {
        public int Iter;
        public double Zr;
        public double Zi;
        public double Dr;
        public double Di;
    }

    private Context? _gpuContext;
    private Accelerator? _gpuAccel;
    private Action<Index1D, ArrayView<RawPixel>, GpuParams>? _gpuKernel;
    private bool _gpuInitFailed;
    public string LastGpuError { get; private set; } = string.Empty;

    private bool TryInitGpu()
    {
        if (_gpuKernel != null) return true;
        if (_gpuInitFailed) return false;
        try
        {
            _gpuContext = Context.Create(b => b.Default());
            _gpuAccel   = _gpuContext.GetPreferredDevice(preferCPU: false).CreateAccelerator(_gpuContext);
            _gpuKernel  = _gpuAccel.LoadAutoGroupedStreamKernel<Index1D, ArrayView<RawPixel>, GpuParams>(Kernel);
            return true;
        }
        catch (Exception ex)
        {
            LastGpuError = ex.Message;
            _gpuInitFailed = true;
            return false;
        }
    }

    private bool TryRenderGpu(double scale, CancellationToken ct)
    {
        if (!TryInitGpu() || _gpuAccel == null || _gpuKernel == null) return false;
        try
        {
            int total = Width * Height;
            using var dev = _gpuAccel.Allocate1D<RawPixel>(total);
            var p = new GpuParams
            {
                Width    = Width,
                Height   = Height,
                CenterX  = CenterX,
                CenterY  = CenterY,
                Scale    = scale,
                MaxIter  = MaxIterations,
                Bailout2 = Bailout2,
            };
            _gpuKernel(total, dev.View, p);
            _gpuAccel.Synchronize();
            if (ct.IsCancellationRequested) return false;
            var raw = new RawPixel[total];
            dev.CopyToCPU(raw);
            Parallel.For(0, total, new ParallelOptions { CancellationToken = ct }, i =>
            {
                if (ct.IsCancellationRequested) return;
                var rp = raw[i];
                ColorBuffer[i] = ColorFor(rp.Iter, rp.Zr, rp.Zi, rp.Dr, rp.Di, MaxIterations, i);
            });
            return true;
        }
        catch (Exception ex)
        {
            LastGpuError = ex.Message;
            return false;
        }
    }

    private static void Kernel(Index1D idx, ArrayView<RawPixel> output, GpuParams p)
    {
        int x = idx % p.Width;
        int y = idx / p.Width;
        if (y >= p.Height) return;
        double cr = p.CenterX + (x - p.Width  * 0.5) * p.Scale;
        double ci = p.CenterY + (y - p.Height * 0.5) * p.Scale;
        double zr = 0.0, zi = 0.0;
        double dr = 0.0, di = 0.0;
        int it = 0;
        int maxIt = p.MaxIter;
        for (; it < maxIt; it++)
        {
            double r2 = zr * zr + zi * zi;
            if (r2 >= p.Bailout2) break;
            double dr_new = (((((((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zr - (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zi) + ((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi)) * zr - (((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zi + (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zr) + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr)) * zi) + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zr - ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zi)) * dr - (((((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zr - (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zi) + ((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi)) * zi + (((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zi + (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zr) + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr)) * zr) + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zi + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zr)) * di) + 1.0);
            double di_new = ((((((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zr - (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zi) + ((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi)) * zr - (((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zi + (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zr) + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr)) * zi) + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zr - ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zi)) * di + (((((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zr - (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zi) + ((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi)) * zi + (((((zr + zr) * zr - (zi + zi) * zi) + (zr * zr - zi * zi)) * zi + (((zr + zr) * zi + (zi + zi) * zr) + (zr * zi + zi * zr)) * zr) + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr)) * zr) + (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zi + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zr)) * dr);
            double zr_new = (((((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zr - ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zi) * zr - (((zr * zr - zi * zi) * zr - (zr * zi + zi * zr) * zi) * zi + ((zr * zr - zi * zi) * zi + (zr * zi + zi * zr) * zr) * zr) * zi) + cr);
