                        finalDrv = drv; finalDiv = div;
                        // Capture DD |z|² for in-set pixels too — the
                        // colour map's in-set branch ignores it, but
                        // emitting unconditionally keeps the ColorForDd
                        // call uniform and avoids a stray Mag of 0.
